import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageClasses() {
  const [classes, setClasses] = useState([]);
  const [formData, setFormData] = useState({
    day: 'Monday', grade: 'Grade 10', subject: '', time_slot: '', teacher: ''
  });

  const fetchClasses = () => {
    axios.get('http://localhost:8081/api/timetable')
      .then(res => setClasses(res.data))
      .catch(err => console.error(err));
  };

  useEffect(() => { fetchClasses(); }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/timetable', formData)
      .then(res => {
        if(res.data.status === "Success") {
            fetchClasses(); 
            setFormData({ day: 'Monday', grade: 'Grade 10', subject: '', time_slot: '', teacher: '' });
            alert("✅ Class added successfully!");
        }
      });
  };

  const handleDelete = (id) => {
    if(window.confirm("Are you sure you want to delete this class?")) {
        axios.delete(`http://localhost:8081/api/timetable/${id}`)
        .then(() => fetchClasses());
    }
  };

  return (
    <div style={{ padding: '30px', backgroundColor: '#f8fafc', minHeight: '100vh' }}>
      <h2 style={{ color: '#15803d', marginBottom: '20px' }}>Manage Classes</h2>

      {/* අලුත් පන්ති ඇතුළත් කරන ෆෝම් එක */}
      <div style={{ backgroundColor: 'white', padding: '20px', borderRadius: '10px', boxShadow: '0 2px 10px rgba(0,0,0,0.05)', marginBottom: '30px' }}>
        <h3 style={{ marginTop: 0, color: '#334155' }}>Add New Class</h3>
        <form onSubmit={handleSubmit} style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px' }}>
          
          {/* 🟢 ඔයා කිව්ව වගේ දවස තෝරන්න Dropdown එකක් */}
          <select value={formData.day} onChange={(e) => setFormData({...formData, day: e.target.value})} style={inputStyle}>
            {['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'].map(d => <option key={d} value={d}>{d}</option>)}
          </select>
          
          {/* 🟢 Grade එක තෝරන්න Dropdown එකක් */}
          <select value={formData.grade} onChange={(e) => setFormData({...formData, grade: e.target.value})} style={inputStyle}>
            {['Grade 06', 'Grade 07', 'Grade 08', 'Grade 09', 'Grade 10', 'Grade 11', 'A/L 2026', 'A/L 2027'].map(g => <option key={g} value={g}>{g}</option>)}
          </select>

          <input type="text" placeholder="Subject (e.g. Mathematics)" value={formData.subject} onChange={(e) => setFormData({...formData, subject: e.target.value})} required style={inputStyle} />
          <input type="text" placeholder="Time Slot (e.g. 03:00 - 05:00)" value={formData.time_slot} onChange={(e) => setFormData({...formData, time_slot: e.target.value})} required style={inputStyle} />
          <input type="text" placeholder="Teacher Name" value={formData.teacher} onChange={(e) => setFormData({...formData, teacher: e.target.value})} required style={inputStyle} />
          
          <button type="submit" style={{ gridColumn: 'span 2', padding: '12px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>
            Add Class
          </button>
        </form>
      </div>

      {/* පන්ති පෙන්වන ටේබල් එක */}
      <div style={{ backgroundColor: 'white', borderRadius: '10px', boxShadow: '0 2px 10px rgba(0,0,0,0.05)', overflow: 'hidden' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead style={{ backgroundColor: '#15803d', color: 'white' }}>
            <tr>
              <th style={thStyle}>Day</th><th style={thStyle}>Grade</th><th style={thStyle}>Subject</th>
              <th style={thStyle}>Time</th><th style={thStyle}>Teacher</th><th style={thStyle}>Action</th>
            </tr>
          </thead>
          <tbody>
            {classes.map((cls) => (
              <tr key={cls.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                <td style={tdStyle}><b>{cls.day}</b></td><td style={tdStyle}>{cls.grade}</td>
                <td style={tdStyle}>{cls.subject}</td><td style={tdStyle}>{cls.time_slot}</td>
                <td style={tdStyle}>{cls.teacher}</td>
                <td style={tdStyle}><button onClick={() => handleDelete(cls.id)} style={{ padding: '6px 12px', backgroundColor: '#ef4444', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>Delete</button></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

const inputStyle = { padding: '12px', border: '1px solid #cbd5e1', borderRadius: '8px', outline: 'none' };
const thStyle = { padding: '15px' };
const tdStyle = { padding: '15px', color: '#475569' };
